[{"order":1,"type":"heading","text":"Using and Consuming Native Plugins in NativeScript"},{"order":2,"type":"paragraph","text":"NativeScript allows developers to access 100% of the native APIs of iOS and Android using JavaScript or TypeScript. One of the most powerful features of the framework is the ability to consume native plugins that bridge the gap between cross-platform application logic and platform-specific capabilities."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"A functioning NativeScript development environment installed on your machine."},{"order":5,"type":"bullet_point","text":"Basic knowledge of TypeScript or JavaScript and NativeScript UI components."},{"order":6,"type":"subheading","text":"Step 1: Installing a Native Plugin"},{"order":7,"type":"paragraph","text":"Plugins in NativeScript are distributed as standard npm packages. For this tutorial, we will use a popular community plugin, such as @nativescript/camera, to demonstrate how to consume native hardware features."},{"order":8,"type":"code","text":"ns plugin add @nativescript/camera"},{"order":9,"type":"subheading","text":"Step 2: Importing the Plugin in Your Code"},{"order":10,"type":"paragraph","text":"Once the plugin is installed via the CLI, you can import it into your TypeScript or JavaScript files just like any other module. Here is an example of importing and using the camera plugin inside a component."},{"order":11,"type":"code","text":"import { Camera } from '@nativescript/camera';
import { Image } from '@nativescript/core';"},{"order":12,"type":"subheading","text":"Step 3: Requesting Permissions and Using the API"},{"order":13,"type":"paragraph","text":"Most native plugins require specific device permissions (such as camera or location access). You must ensure permissions are requested before calling the native APIs."},{"order":14,"type":"code","text":"async function onTakePicture(imageComponent: Image) {
  try {
    const isAvailable = Camera.isAvailable();
    if (isAvailable) {
      await Camera.requestPermissions();
      const imageAsset = await Camera.takePicture({
        width: 300,
        height: 300,
        keepAspectRatio: true
      });
      imageComponent.src = imageAsset;
    }
  } catch (error) {
    console.error("Error taking picture: ", error);
  }
}"},{"order":15,"type":"subheading","text":"Step 4: Handling Platform-Specific Code"},{"order":16,"type":"paragraph","text":"Sometimes plugins require fine-tuning for either iOS or Android. NativeScript provides the isAndroid and isIOS constants, as well as android and ios namespaces, to handle platform branches seamlessly."},{"order":17,"type":"code","text":"import { Application, supuestoPlatform } from '@nativescript/core';

if (Application.ios) {
  console.log("Running on iOS devices");
} else if (Application.android) {
  console.log("Running on Android devices");
}"},{"order":18,"type":"subheading","text":"Conclusion"},{"order":19,"type":"paragraph","text":"By leveraging native plugins, you can easily extend your NativeScript applications to interact deeply with device hardware. Always remember to check plugin documentation for required platform-specific configurations in your App_Resources folder."}]
